import networkx as nx
import itertools

def find_graph():
    for edges in itertools.combinations(itertools.combinations(range(13), 2), 9):
        G = nx.Graph()
        G.add_edges_from(edges)
        if all(1 <= G.degree(v) <= 4 for v in G.nodes()) and 9 <= len(G.edges()) <= 17 and nx.algorithms.coloring.greedy_color(G) <= 2 and nx.algorithms.coloring.greedy_color(G) >= 3:
            return list(G.edges())
    return "UNSATISFIABLE"

print(find_graph())
